messages.content:
{
  "title": "agent.completions.message.InputAudio",
  "description": "Audio input for multimodal messages.",
  "type": "object",
  "properties": {
    "data": {
      "description": "Base64-encoded audio data.",
      "type": "string"
    },
    "format": {
      "description": "The audio format (e.g., \"wav\", \"mp3\").",
      "type": "string"
    }
  }
}

{
  "title": "functions.expression.ImageInputSchema",
  "description": "Schema for an image input (URL or base64-encoded).",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the expected image.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ImageInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.AnyOfInputSchema",
  "description": "Schema for a union of possible types - input must match at least one.",
  "type": "object",
  "properties": {
    "anyOf": {
      "description": "The possible schemas that the input can match.",
      "type": "array",
      "items": {
        "$ref": "functions.expression.InputSchema"
      }
    }
  }
}

{
  "title": "agent.completions.message.File",
  "description": "A file attachment for multimodal input.",
  "type": "object",
  "properties": {
    "file_data": {
      "description": "Base64-encoded file data.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_id": {
      "description": "The ID of a previously uploaded file.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "file_url": {
      "description": "A URL to fetch the file from.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "filename": {
      "description": "The filename for display purposes.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    }
  }
}

{
  "title": "agent.completions.message.ImageUrlDetail",
  "description": "Detail level for image processing.",
  "anyOf": [
    {
      "title": "Auto",
      "description": "Let the model decide the detail level.",
      "type": "string",
      "enum": [
        "auto"
      ]
    },
    {
      "title": "Low",
      "description": "Low detail mode (faster, less tokens).",
      "type": "string",
      "enum": [
        "low"
      ]
    },
    {
      "title": "High",
      "description": "High detail mode (more accurate, more tokens).",
      "type": "string",
      "enum": [
        "high"
      ]
    }
  ]
}

{
  "title": "agent.completions.message.AssistantToolCallExpression",
  "description": "A function call expression.",
  "type": "object",
  "properties": {
    "function": {
      "description": "The function expression.

A value that can be either a literal or an expression.

This allows Function definitions to mix static values with dynamic
expressions. During compilation, expressions are evaluated while
literal values pass through unchanged.

# Example

Literal value:
```json
"hello world"
```

JMESPath expression:
```json
{"$jmespath": "input.greeting"}
```

Starlark expression:
```json
{"$starlark": "input['greeting']"}
```",
      "anyOf": [
        {
          "title": "Expression",
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "title": "Value",
          "description": "A literal value.",
          "$ref": "agent.completions.message.AssistantToolCallFunctionExpression"
        }
      ]
    },
    "id": {
      "description": "The tool call ID expression.

A value that can be either a literal or an expression.

This allows Function definitions to mix static values with dynamic
expressions. During compilation, expressions are evaluated while
literal values pass through unchanged.

# Example

Literal value:
```json
"hello world"
```

JMESPath expression:
```json
{"$jmespath": "input.greeting"}
```

Starlark expression:
```json
{"$starlark": "input['greeting']"}
```",
      "anyOf": [
        {
          "title": "Expression",
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "title": "Value",
          "description": "A literal value.",
          "type": "string"
        }
      ]
    },
    "type": {
      "type": "string",
      "enum": [
        "function"
      ]
    }
  }
}
